package multiformats

import multiformats.varint.VarInt

final case class MulticodecValidationError(
    private val message: String = "",
    private val cause: Throwable = None.orNull
) extends Exception(message, cause)

object multicodec:

  // format: off
  // generateMulticodec: begin //
  enum MulticodecTag:
    case cid
    case encryption
    case filecoin
    case hash
    case holochain
    case ipld
    case key
    case libp2p
    case multiaddr
    case multiformat
    case multihash
    case multikey
    case multisig
    case namespace
    case nonce
    case serialization
    case shelter
    case softhash
    case transport
    case varsig
    case vlad
    case zeroxcert

  enum MulticodecStatus:
    case deprecated, draft, permanent

  enum Multicodec(val tag: MulticodecTag, val code: VarInt, val status: MulticodecStatus, val description: Option[String]):
    case identity                       extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x00), MulticodecStatus.permanent, Some("raw binary"))
    case cidv1                          extends Multicodec(MulticodecTag.cid, VarInt.encode(0x01), MulticodecStatus.permanent, Some("CIDv1"))
    case cidv2                          extends Multicodec(MulticodecTag.cid, VarInt.encode(0x02), MulticodecStatus.draft, Some("CIDv2"))
    case cidv3                          extends Multicodec(MulticodecTag.cid, VarInt.encode(0x03), MulticodecStatus.draft, Some("CIDv3"))
    case ip4                            extends Multicodec(MulticodecTag.multiaddr, VarInt.encode(0x04), MulticodecStatus.permanent, None)
    case tcp                            extends Multicodec(MulticodecTag.multiaddr, VarInt.encode(0x06), MulticodecStatus.permanent, None)
    case sha1                           extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x11), MulticodecStatus.permanent, None)
    case sha2_256                       extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x12), MulticodecStatus.permanent, None)
    case sha2_512                       extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x13), MulticodecStatus.permanent, None)
    case sha3_512                       extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x14), MulticodecStatus.permanent, None)
    case sha3_384                       extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x15), MulticodecStatus.permanent, None)
    case sha3_256                       extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x16), MulticodecStatus.permanent, None)
    case sha3_224                       extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x17), MulticodecStatus.permanent, None)
    case shake_128                      extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x18), MulticodecStatus.draft, None)
    case shake_256                      extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x19), MulticodecStatus.draft, None)
    case keccak_224                     extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x1a), MulticodecStatus.draft, Some("keccak has variable output length. The number specifies the core length"))
    case keccak_256                     extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x1b), MulticodecStatus.draft, None)
    case keccak_384                     extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x1c), MulticodecStatus.draft, None)
    case keccak_512                     extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x1d), MulticodecStatus.draft, None)
    case blake3                         extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x1e), MulticodecStatus.draft, Some("BLAKE3 has a default 32 byte output length. The maximum length is (2^64)-1 bytes."))
    case sha2_384                       extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x20), MulticodecStatus.permanent, Some("aka SHA-384; as specified by FIPS 180-4."))
    case dccp                           extends Multicodec(MulticodecTag.multiaddr, VarInt.encode(0x21), MulticodecStatus.draft, None)
    case murmur3_x64_64                 extends Multicodec(MulticodecTag.hash, VarInt.encode(0x22), MulticodecStatus.permanent, Some("The first 64-bits of a murmur3-x64-128 - used for UnixFS directory sharding."))
    case murmur3_32                     extends Multicodec(MulticodecTag.hash, VarInt.encode(0x23), MulticodecStatus.draft, None)
    case ip6                            extends Multicodec(MulticodecTag.multiaddr, VarInt.encode(0x29), MulticodecStatus.permanent, None)
    case ip6zone                        extends Multicodec(MulticodecTag.multiaddr, VarInt.encode(0x2a), MulticodecStatus.draft, None)
    case ipcidr                         extends Multicodec(MulticodecTag.multiaddr, VarInt.encode(0x2b), MulticodecStatus.draft, Some("CIDR mask for IP addresses"))
    case path                           extends Multicodec(MulticodecTag.namespace, VarInt.encode(0x2f), MulticodecStatus.permanent, Some("Namespace for string paths. Corresponds to `/` in ASCII."))
    case multicodec                     extends Multicodec(MulticodecTag.multiformat, VarInt.encode(0x30), MulticodecStatus.draft, None)
    case multihash                      extends Multicodec(MulticodecTag.multiformat, VarInt.encode(0x31), MulticodecStatus.draft, None)
    case multiaddr                      extends Multicodec(MulticodecTag.multiformat, VarInt.encode(0x32), MulticodecStatus.draft, None)
    case multibase                      extends Multicodec(MulticodecTag.multiformat, VarInt.encode(0x33), MulticodecStatus.draft, None)
    case varsig                         extends Multicodec(MulticodecTag.multiformat, VarInt.encode(0x34), MulticodecStatus.draft, Some("Variable signature (varsig) multiformat"))
    case dns                            extends Multicodec(MulticodecTag.multiaddr, VarInt.encode(0x35), MulticodecStatus.permanent, None)
    case dns4                           extends Multicodec(MulticodecTag.multiaddr, VarInt.encode(0x36), MulticodecStatus.permanent, None)
    case dns6                           extends Multicodec(MulticodecTag.multiaddr, VarInt.encode(0x37), MulticodecStatus.permanent, None)
    case dnsaddr                        extends Multicodec(MulticodecTag.multiaddr, VarInt.encode(0x38), MulticodecStatus.permanent, None)
    case protobuf                       extends Multicodec(MulticodecTag.serialization, VarInt.encode(0x50), MulticodecStatus.draft, Some("Protocol Buffers"))
    case cbor                           extends Multicodec(MulticodecTag.ipld, VarInt.encode(0x51), MulticodecStatus.permanent, Some("CBOR"))
    case raw                            extends Multicodec(MulticodecTag.ipld, VarInt.encode(0x55), MulticodecStatus.permanent, Some("raw binary"))
    case dbl_sha2_256                   extends Multicodec(MulticodecTag.multihash, VarInt.encode(0x56), MulticodecStatus.draft, None)
    case rlp                            extends Multicodec(MulticodecTag.serialization, VarInt.encode(0x60), MulticodecStatus.draft, Some("recursive length prefix"))
    case bencode                        extends Multicodec(MulticodecTag.serialization, VarInt.encode(0x63), MulticodecStatus.draft, Some("bencode"))
    case dag_pb                         extends Multicodec(MulticodecTag.ipld, VarInt.encode(0x70), MulticodecStatus.permanent, Some("MerkleDAG protobuf"))
    case dag_cbor                       extends Multicodec(MulticodecTag.ipld, VarInt.encode(0x71), MulticodecStatus.permanent, Some("MerkleDAG cbor"))
