    case eth_block_list                 extends Multicodec(MulticodecTag.ipld, VarInt.encode(0x91), MulticodecStatus.permanent, Some("Ethereum Header List (RLP)"))
    case eth_tx_trie                    extends Multicodec(MulticodecTag.ipld, VarInt.encode(0x92), MulticodecStatus.permanent, Some("Ethereum Transaction Trie (Eth-Trie)"))
    case eth_tx                         extends Multicodec(MulticodecTag.ipld, VarInt.encode(0x93), MulticodecStatus.permanent, Some("Ethereum Transaction (MarshalBinary)"))
    case eth_tx_receipt_trie            extends Multicodec(MulticodecTag.ipld, VarInt.encode(0x94), MulticodecStatus.permanent, Some("Ethereum Transaction Receipt Trie (Eth-Trie)"))
    case eth_tx_receipt                 extends Multicodec(MulticodecTag.ipld, VarInt.encode(0x95), MulticodecStatus.permanent, Some("Ethereum Transaction Receipt (MarshalBinary)"))
    case eth_state_trie                 extends Multicodec(MulticodecTag.ipld, VarInt.encode(0x96), MulticodecStatus.permanent, Some("Ethereum State Trie (Eth-Secure-Trie)"))
    case eth_account_snapshot           extends Multicodec(MulticodecTag.ipld, VarInt.encode(0x97), MulticodecStatus.permanent, Some("Ethereum Account Snapshot (RLP)"))
    case eth_storage_trie               extends Multicodec(MulticodecTag.ipld, VarInt.encode(0x98), MulticodecStatus.permanent, Some("Ethereum Contract Storage Trie (Eth-Secure-Trie)"))
